+import { describe, expect, setSystemTime, test } from "bun:test";
+import type Anthropic from "@anthropic-ai/sdk";
+import { LlmStreamError } from "../../../../../../src/orchestration/agent-runtime/llm/errors.js";
+import type { SignedBlock } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-file.js";
+import { hostedStreamEvents, type HostedAnswer, type StepEvent } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.js";
+import type { HostStepItem } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/host-gate.js";
+
+const THOUGHT: SignedBlock = { type: "thinking", thinking: "Plan the answer.", signature: "sig-1" };
+const STOP: HostStepItem = { kind: "stop", stopReason: "end_turn", usage: null };
+const TEXT_CHUNKS = ["One", " two", " three"];
+
+/** A step that thinks, then writes, as the engine's hook passes it on. `beforeStop` runs before the stop chunk, and
+ *  `end` decides whether the step sends its stop chunk.
+ *  @yields {StepEvent} The step's events. */
+async function* thinkThenWrite(beforeStop: () => void, end: "stop" | "none" = "stop"): AsyncGenerator<StepEvent> {
+  yield { kind: "item", item: { kind: "thinking", index: 0, text: "Plan the" } };
+  for (const text of TEXT_CHUNKS) {
+    await Bun.sleep(5);
+    yield { kind: "item", item: { kind: "text", index: 1, text } };
+  }
+  beforeStop();
+  if (end === "stop") yield { kind: "item", item: STOP };
+  yield { kind: "done" };
+}
+
+const STEP_FAILURE = new Error("529 overloaded");
+
+async function streamed(events: AsyncIterable<StepEvent>, read: () => readonly SignedBlock[], onProgress: () => void) {
+  const out: Anthropic.RawMessageStreamEvent[] = [];
+  const answers: HostedAnswer[] = [];
+  for await (const event of hostedStreamEvents(events, { read }, 0, "claude-test", async () => STEP_FAILURE, (answer) => answers.push(answer), onProgress)) out.push(event);
+  return { out, answers };
+}
+
+function described(event: Anthropic.RawMessageStreamEvent): string {
+  if (event.type === "content_block_delta") return `${event.type}:${event.index}:${event.delta.type}`;
+  if (event.type === "content_block_start" || event.type === "content_block_stop") return `${event.type}:${event.index}`;
+  return event.type;
+}
+
+describe("hostedStreamEvents", () => {
+  test("a response that writes on after its thinking completes once the engine writes the thinking row at its end, in Anthropic event order", async () => {
+    const signed: SignedBlock[] = [];
+    let progress = 0;
+    // The engine writes the thinking block's row only after the response's last chunk.
+    const { out, answers } = await streamed(thinkThenWrite(() => { setTimeout(() => signed.push(THOUGHT), 50); }), () => signed, () => { progress += 1; });
+
+    expect(out.map(described)).toEqual([
+      "message_start",
+      "content_block_start:0", "content_block_delta:0:thinking_delta", "content_block_delta:0:thinking_delta", "content_block_delta:0:signature_delta", "content_block_stop:0",
+      "content_block_start:1", "content_block_delta:1:text_delta", "content_block_delta:1:text_delta", "content_block_delta:1:text_delta", "content_block_stop:1",
+      "message_delta", "message_stop",
+    ]);
+    expect(out.find((event) => event.type === "content_block_delta" && event.delta.type === "signature_delta")).toMatchObject({ delta: { signature: "sig-1" } });
+    expect(answers).toEqual([{ message: { role: "assistant", content: [THOUGHT, { type: "text", text: TEXT_CHUNKS.join("") }] }, stopReason: "end_turn" }]);
+    // The first text chunk ends the thinking block; each later chunk that the stream held back, the stop chunk
+    // included, counts as progress, and the polls after the last chunk do not.
+    expect(progress).toBe(3);
+  });
+
+  test("a signed row still missing after the step's stop chunk fails transient", async () => {
+    const start = Date.now();
+    let stopped = false;
+    try {
+      const failed = streamed(thinkThenWrite(() => { stopped = true; }), () => {
+        if (stopped) setSystemTime(new Date(start + 60_000));
+        return [];
+      }, () => {});
+      const error = await failed.then(() => undefined, (cause: unknown) => cause);
+      expect(error).toBeInstanceOf(LlmStreamError);
+      expect(error).toMatchObject({ kind: "transient", message: expect.stringContaining("wrote no row") });
+    } finally {
+      setSystemTime();
+    }
+  });
+
+  test("a step that ends without its stop chunk while a row is pending fails with the service's answer", async () => {
+    const error = await streamed(thinkThenWrite(() => {}, "none"), () => [], () => {}).then(() => undefined, (cause: unknown) => cause);
+    expect(error).toBe(STEP_FAILURE);
+  });
+});

