@@ -0,0 +1,66 @@
+import { TemplateError } from "./types.js";
+import type { TemplateToken } from "./types.js";
+
+export type TemplateNode =
+  | { kind: "text"; value: string; position: number }
+  | { kind: "variable"; path: string; escaped: boolean; position: number }
+  | { kind: "block"; block: "if" | "each"; path: string; body: TemplateNode[]; position: number };
+
+interface OpenBlockFrame {
+  block: "if" | "each";
+  path: string;
+  position: number;
+  body: TemplateNode[];
+}
+
+export function parse(tokens: readonly TemplateToken[]): TemplateNode[] {
+  const root: TemplateNode[] = [];
+  const stack: OpenBlockFrame[] = [];
+
+  const currentBody = (): TemplateNode[] =>
+    stack.length > 0 ? stack[stack.length - 1]!.body : root;
+
+  for (const token of tokens) {
+    switch (token.kind) {
+      case "text":
+      case "variable":
+        currentBody().push(token);
+        break;
+      case "open":
+        stack.push({
+          block: token.block,
+          path: token.path,
+          position: token.position,
+          body: [],
+        });
+        break;
+      case "close": {
+        const frame = stack.pop();
+        if (frame === undefined) {
+          throw new TemplateError(`Unexpected closing tag {{/${token.block}}}`, token.position);
+        }
+        if (frame.block !== token.block) {
+          throw new TemplateError(
+            `Mismatched closing tag {{/${token.block}}} for {{#${frame.block}}}`,
+            token.position,
+          );
+        }
+        currentBody().push({
+          kind: "block",
+          block: frame.block,
+          path: frame.path,
+          body: frame.body,
+          position: frame.position,
+        });
+        break;
+      }
+    }
+  }
+
+  if (stack.length > 0) {
+    const unclosed = stack[stack.length - 1]!;
+    throw new TemplateError(`Unclosed {{#${unclosed.block}}} block`, unclosed.position);
+  }
+
+  return root;
+}
