--- /dev/null
+++ b/parser.ts
@@ -0,0 +1,70 @@
+import { TemplateError, type TemplateToken } from "./types.js";
+
+export type TemplateNode =
+  | { kind: "text"; value: string }
+  | { kind: "variable"; path: string; escaped: boolean }
+  | { kind: "block"; block: "if" | "each"; path: string; children: TemplateNode[] };
+
+interface OpenBlockFrame {
+  block: "if" | "each";
+  path: string;
+  position: number;
+  children: TemplateNode[];
+}
+
+export function parse(tokens: readonly TemplateToken[]): TemplateNode[] {
+  const root: TemplateNode[] = [];
+  const stack: OpenBlockFrame[] = [];
+
+  const currentChildren = (): TemplateNode[] =>
+    stack.length > 0 ? stack[stack.length - 1]!.children : root;
+
+  for (const token of tokens) {
+    switch (token.kind) {
+      case "text":
+        currentChildren().push({ kind: "text", value: token.value });
+        break;
+      case "variable":
+        currentChildren().push({
+          kind: "variable",
+          path: token.path,
+          escaped: token.escaped,
+        });
+        break;
+      case "open":
+        stack.push({
+          block: token.block,
+          path: token.path,
+          position: token.position,
+          children: [],
+        });
+        break;
+      case "close": {
+        const openFrame = stack.pop();
+        if (!openFrame) {
+          throw new TemplateError(`Unexpected closing "${token.block}" tag`, token.position);
+        }
+        if (openFrame.block !== token.block) {
+          throw new TemplateError(
+            `Mismatched closing "${token.block}" tag for "${openFrame.block}"`,
+            token.position,
+          );
+        }
+        currentChildren().push({
+          kind: "block",
+          block: openFrame.block,
+          path: openFrame.path,
+          children: openFrame.children,
+        });
+        break;
+      }
+    }
+  }
+
+  if (stack.length > 0) {
+    const unclosed = stack[stack.length - 1]!;
+    throw new TemplateError(`Unclosed "${unclosed.block}" block`, unclosed.position);
+  }
+
+  return root;
+}
