+import { TemplateError, type TemplateToken } from "./types.js";
+
+export type BlockNode = {
+  kind: "block";
+  block: "if" | "each";
+  path: string;
+  position: number;
+  children: TemplateNode[];
+};
+
+export type TemplateNode =
+  | Extract<TemplateToken, { kind: "text" | "variable" }>
+  | BlockNode;
+
+/**
+ * Builds the nested block tree from a token stream. Each close matches the innermost open block.
+ * Throws TemplateError at the closing offset for an unexpected or mismatched close, and at the
+ * innermost unclosed block's opening offset when input ends inside a block.
+ */
+export function parse(tokens: readonly TemplateToken[]): TemplateNode[] {
+  const root: TemplateNode[] = [];
+  const open: BlockNode[] = [];
+  const current = () => open.at(-1)?.children ?? root;
+
+  for (const token of tokens) {
+    switch (token.kind) {
+      case "open": {
+        const node: BlockNode = { ...token, kind: "block", children: [] };
+        current().push(node);
+        open.push(node);
+        break;
+      }
+      case "close": {
+        const innermost = open.pop();
+        if (innermost === undefined) {
+          throw new TemplateError(`Unexpected {{/${token.block}}}`, token.position);
+        }
+        if (innermost.block !== token.block) {
+          throw new TemplateError(
+            `Mismatched {{/${token.block}}}, expected {{/${innermost.block}}}`,
+            token.position,
+          );
+        }
+        break;
+      }
+      default:
+        current().push(token);
+    }
+  }
+
+  const unclosed = open.at(-1);
+  if (unclosed !== undefined) {
+    throw new TemplateError(`Unclosed {{#${unclosed.block}}}`, unclosed.position);
+  }
+  return root;
+}
